n7_chr = os.path.join(os.path.dirname(__file__), os.pardir,  "n7_chr")
n7_chr_mod = os.path.join(os.path.dirname(__file__), os.pardir,  "n7_chr_mod")

if not os.path.exists(n7_chr):
    print("chr.afs has not been unpacked. aborting.")
    sys.exit(1)
if not os.path.exists(n7_chr_mod):
    os.mkdir(n7_chr_mod)

counter = 0
for fname in os.listdir(n7_chr):
    name, ext = os.path.splitext(fname)
    if not ext.upper() == ".R11": continue
    name_base = name[:-1] if (len(name) >= 7 and name[-1] in ("D", "N")) else name
    if name_base not in nullify_coords: continue
    nullify = nullify_coords[name_base]
    images = unpack_r11(open(os.path.join(n7_chr, fname), "rb"))
    if len(images) != 1:
        print(name+":", len(images), "images extracted from file instead of 1. aborting.")
        sys.exit(1)
    im = images[0]
    color = (0, 0, 8, 0) # this is what they mainly use for the transparent background, not sure why
    if im.mode == "P":
        palette = im.getpalette("RGBA")
        palette = [tuple(palette[i:i+4]) for i in range(0, len(palette), 4)]
        if color not in palette:
            color = (0, 0, 0, 0)
            if color not in palette:
                for x in palette:
                    if not x[3] == 0: continue
                    color = x
                    break
                if color not in palette:
                    print(name+": failed to find a transparent color in the palette. aborting.")
                    sys.exit(1)
    for coord in nullify:
        im.putpixel(coord, color)
    make_r11(im, os.path.join(n7_chr_mod, fname), True)
    counter += 1
print(counter, "images processed")
